TRANSLATIONS = {"en-CA": EN, "fr-CA": FR}


def get_translation(language: str):
    translations = TRANSLATIONS.get(language, EN)

    def translate(key: str) -> str:
        return translations.get(key, EN.get(key, key))

    return translate
